import { Injectable } from '@angular/core';
import { BigNumber, Contract, ethers } from 'ethers';
import { switchMap } from 'rxjs/operators';
import { forkJoin, Observable, of } from 'rxjs';

import { contractAbi, decTokenBase64Image } from './contract.definition';
import { Environment } from '@environments/environment.definitions';
import ethereum from '@core/utils/ethereum-types';

interface ContractData {
  address: string,
  decimals: number,
  name: string,
  symbol: string,
}

interface DecContract extends Contract {
  balanceOf(address: string): Promise<string>;
  decimals(): Promise<number>;
  image(): string;
  name(): Promise<string>;
  symbol(): Promise<string>;
  transfer(address: string, amount: BigNumber): Promise<{ hash: string }>;
}

@Injectable()
export class ContractService {

  constructor(
    private environment: Environment,
  ) {
  }

  public getBalance(address: string): Promise<string> {
    return this.getContractInstant().balanceOf(address).catch(() => '0');
  }

  public getContractInstant(): DecContract {
    const provider = new ethers.providers.Web3Provider(ethereum);

    return new ethers.Contract(this.environment.decentrContractAddress, contractAbi, provider.getSigner()) as DecContract;
  }

  public getContractData(): Observable<ContractData> {
    return of(this.getContractInstant()).pipe(
      switchMap((contract) =>
        forkJoin({
          address: of(contract.address),
          decimals: contract.decimals(),
          image: of(decTokenBase64Image),
          name: contract.name(),
          symbol: contract.symbol(),
        }),
      ),
    );
  }
}
