import { Injectable } from '@angular/core';
import { coerceArray } from '@angular/cdk/coercion';
import { combineLatest, Observable, of, throwError } from 'rxjs';
import { map, mapTo, mergeMap, take, tap } from 'rxjs/operators';
import { SwapDetails, SwapListPaginationOptions, Wallet } from 'decentr-js';

import charon from '../../../utils/charon-types';
import { DECENTR_LINK, MICRO_DIVISOR, NetworkDescription, NetworkService } from '../networks.definitions';
import { Environment } from '../../../../../../../../environments/environment.definitions';

@Injectable()
export class CharonService implements NetworkService {

  constructor(
    private environment: Environment,
  ) {
  }

  public isAPIAvailable(): boolean {
    return !!charon?.connect;
  }

  public isConnecting(): Observable<boolean> {
    return of(false);
  }

  public connect(): Promise<boolean> {
    if (!this.isAPIAvailable()) {
      window.open(DECENTR_LINK, '_blank');
      return Promise.resolve(false);
    }

    return this.checkActiveNetworkAllowed(this.environment.decentrAllowedChainIds).pipe(
      mergeMap((isAllowed) => isAllowed ? of(undefined) : throwError(new Error('Please select Mainnet network in Charon'))),
      tap(() => charon.connect()),
      mapTo(true),
      take(1),
    ).toPromise();
  }

  public getNetwork(): Observable<NetworkDescription> {
    return charon.getNetwork().pipe(
      map((networkId) => ({
        chainId: networkId,
        name: networkId,
      })),
    );
  }

  public getBalance(): Observable<string> {
    return charon.getBalance().pipe(
      map((balance) => (+balance / MICRO_DIVISOR).toString()),
    );
  }

  public checkActiveNetworkAllowed(allowedChainId: string | string[]): Observable<boolean> {
    return this.getNetwork().pipe(
      map(({ chainId }) => coerceArray(allowedChainId).includes(chainId.toString())),
    );
  }

  public getWalletAddress(): Observable<string> {
    return charon?.getWalletAddress();
  }

  public isConnected(): Observable<boolean> {
    if (!this.isAPIAvailable()) {
      return of(false);
    }

    return combineLatest([
      this.checkActiveNetworkAllowed(this.environment.decentrAllowedChainIds),
      charon.isConnected(),
    ]).pipe(
      map((conditions) => conditions.every(Boolean)),
    );
  }

  public createSwap(receiverAddress: Wallet['address'], txHash: string, signature: string): Promise<SwapDetails> {
    return charon.createSwap(receiverAddress, txHash, signature);
  }

  public getSwapById(swapId: number): Promise<SwapDetails> {
    return charon.getSwapById(swapId);
  }

  public getSwapList(paginationOptions?: SwapListPaginationOptions): Promise<SwapDetails[]> {
    return charon.getSwapList(paginationOptions);
  }

  public transferCoin(): Promise<string> {
    return Promise.reject(new Error());
  }
}
