import { Injectable } from '@angular/core';

import { CharonService } from './charon';
import { MetamaskService } from './metamask';
import { NetworkService, SwapDestinationNetwork } from './networks.definitions';

@Injectable()
export class NetworkResolverService {

  constructor(
    private charonService: CharonService,
    private metamaskService: MetamaskService,
  ) {
  }

  public resolve(network: SwapDestinationNetwork): NetworkService {
    switch (network) {
      case SwapDestinationNetwork.DEC:
        return this.charonService;
      case SwapDestinationNetwork.ETH:
        return this.metamaskService;
    }
  }
}
